// TextEncoder produces UTF-8 bytes in Node.js and browsers
const enc = new TextEncoder();

function showEncoding(char) {
  const bytes = enc.encode(char);
  const hex = Array.from(bytes)
    .map(b => '0x' + b.toString(16).toUpperCase().padStart(2, '0'))
    .join(' ');
  const cp = 'U+' + char.codePointAt(0).toString(16).toUpperCase().padStart(4, '0');
  console.log(`'${char}' ${cp} → ${bytes.length} byte(s): ${hex}`);
}

showEncoding('A');   // 'A' U+0041 → 1 byte:  0x41
showEncoding('é');   // 'é' U+00E9 → 2 bytes: 0xC3 0xA9
showEncoding('中');  // '中' U+4E2D → 3 bytes: 0xE4 0xB8 0xAD
showEncoding('😀'); // '😀' U+1F600 → 4 bytes: 0xF0 0x9F 0x98 0x80

// Three different length measurements for the same string
const s = '😀';
console.log('UTF-16 code units (.length):', s.length);    // 2
console.log('Unicode code points ([...]):', [...s].length); // 1
console.log('UTF-8 bytes:', enc.encode(s).length);         // 4

// Decode UTF-8 bytes back to string
const dec = new TextDecoder('utf-8');
const bytes = Uint8Array.from([0xE4, 0xB8, 0xAD]);
console.log('Decoded:', dec.decode(bytes)); // 中

// Combining characters: same visual, different bytes
const precomposed = '\u00E9';      // é as U+00E9 (single code point)
const decomposed  = 'e\u0301';   // e + U+0301 (combining acute accent)
console.log('Same display?', precomposed, decomposed); // é é
console.log('=== equal?', precomposed === decomposed); // false
console.log('NFC equal?', precomposed.normalize('NFC') === decomposed.normalize('NFC')); // true

// ── Surrogate pair internals for 😀 (U+1F600) ─────────────────
const emoji = '😀';
console.log('length (UTF-16 units):', emoji.length);              // 2
console.log('codePointAt(0):', emoji.codePointAt(0).toString(16)); // 1f600
console.log('charCodeAt(0):', emoji.charCodeAt(0).toString(16));   // d83d (high surrogate)
console.log('charCodeAt(1):', emoji.charCodeAt(1).toString(16));   // de00 (low surrogate)

// Correct iteration over code points
for (const cp of emoji) {
  console.log('code point:', cp.codePointAt(0).toString(16)); // 1f600 (one iteration)
}

// ── Regional indicator sequences (flags) ──────────────────────
// 🇺🇸 = U+1F1FA (🇺) + U+1F1F8 (🇸)
const flag = '\u{1F1FA}\u{1F1F8}';
console.log('flag display:', flag);              // 🇺🇸
console.log('flag code points:', [...flag].length); // 2
console.log('flag .length:', flag.length);          // 4 (4 UTF-16 code units)

// ── ZWJ sequences (woman scientist) ──────────────────────────
// U+1F469 (woman) + U+200D (ZWJ) + U+1F52C (microscope)
const scientist = '\u{1F469}\u200D\u{1F52C}';
console.log('scientist:', scientist);                  // 👩‍🔬
console.log('code points:', [...scientist].length);   // 3
console.log('.length:', scientist.length);             // 5 (UTF-16 code units)

// ── Intl.Segmenter: correct grapheme cluster counting ─────────
const seg = new Intl.Segmenter();
function graphemeCount(str) {
  return [...seg.segment(str)].length;
}
console.log('graphemes in 😀:', graphemeCount('😀'));       // 1
console.log('graphemes in 🇺🇸:', graphemeCount('\u{1F1FA}\u{1F1F8}')); // 1
console.log('graphemes in 👩‍🔬:', graphemeCount('\u{1F469}\u200D\u{1F52C}')); // 1

// ── Unicode normalization ─────────────────────────────────────
const pre = '\u00E9';    // é precomposed (U+00E9)
const dec = 'e\u0301'; // é decomposed (e + combining acute)
console.log('visual same:', pre, '===', dec);
console.log('byte same:', pre === dec);                         // false
console.log('NFC same:', pre.normalize('NFC') === dec.normalize('NFC')); // true
